TLM.f("Tempora/Epi1-0",{"officium":"Sanctæ Familiæ Jesu Mariæ Joseph","rule":["Gloria","Credo","Prefatio=Epi","No Sunday Commemoratio"],"sections":{"Introitus":[{"k":"rubric","la":"Prov 23:24; 23:25"},{"k":"text","la":"Exsúltat gáudio pater Justi, gáudeat Pater tuus et Mater tua, et exsúltet quæ génuit te."},{"k":"ref","la":"Ps 83:2-3"},{"k":"text","la":"Quam dilécta tabernácula tua, Dómine virtútum! concupíscit et déficit ánima mea in átria Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Exsúltat gáudio pater Justi, gáudeat Pater tuus et Mater tua, et exsúltet quæ génuit te."}],"Oratio":[{"k":"text","la":"Dómine Jesu Christe, qui, Maríæ et Joseph súbditus, domésticam vitam ineffabílibus virtútibus consecrásti: fac nos, utriúsque auxílio, Famíliæ sanctæ tuæ exémplis ínstrui; et consórtium cónsequi sempitérnum:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses"},{"k":"ref","la":"Col 3:12-17"},{"k":"text","la":"Fratres: Indúite vos sicut elécti Dei, sancti et dilécti, víscera misericórdiæ, benignitátem, humilitátem, modéstiam, patiéntiam: supportántes ínvicem, et donántes vobismetípsis, si quis advérsus áliquem habet querélam: sicut et Dóminus donávit vobis, ita et vos. Super ómnia autem hæc caritátem habéte, quod est vínculum perfectiónis: et pax Christi exsúltet in córdibus vestris, in qua et vocáti estis in uno córpore: et grati estóte. Verbum Christi hábitet in vobis abundánter, in omni sapiéntia, docéntes et commonéntes vosmetípsos psalmis, hymnis et cánticis spirituálibus, in grátia cantántes in córdibus vestris Deo. Omne, quodcúmque fácitis in verbo aut in ópere, ómnia in nómine Dómini Jesu Christi, grátias agéntes Deo et Patri per ipsum."}],"Graduale":[{"k":"ref","la":"Ps 26:4"},{"k":"text","la":"Unam pétii a Dómino, hanc requíram: ut inhábitem in domo Dómini ómnibus diébus vitæ meæ."},{"k":"ref","la":"Ps 83:5"},{"k":"text","la":"Beáti, qui hábitant in domo tua, Dómine: in sǽcula sæculórum laudábunt te. Allelúja, allelúja,"},{"k":"ref","la":"Isa 45:15"},{"k":"text","la":"Vere tu es Rex abscónditus, Deus Israël Salvátor. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja,"},{"k":"rubric","la":"Prov 8:34"},{"k":"text","la":"Beátus homo qui audit me, et qui vígilat ad fores meas cotídie, et obsérvat ad postes óstii mei. Allelúja, allelúja,"},{"k":"ref","la":"Col 3:3"},{"k":"text","la":"Vita nostra est abscóndita cum Christo in Deo. Allelúja."}],"Tractus":[{"k":"ref","la":"Heb 10:5"},{"k":"text","la":"Hóstiam et oblatiónem noluísti, corpus autem aptásti mihi."},{"k":"ref","la":"Ps 39:7-8"},{"k":"text","la":"Holocáustum et pro peccáto non postulásti: tunc dixi: Ecce, vénio."},{"k":"ref","la":"Heb 10:7"},{"k":"text","la":"In cápite libri scriptum est de me: Ut fáciam, Deus, voluntátem tuam.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 2:42-52"},{"k":"text","la":"Cum factus esset Jesus annórum duódecim, ascendéntibus illis Jerosólymam secúndum consuetúdinem diéi festi, consummatísque diébus, cum redírent, remánsit puer Jesus in Jerúsalem, et non cognovérunt paréntes ejus. Existimántes autem illum esse in comitátu, venérunt iter diéi, et requirébant eum inter cognátos et notos. Et non inveniéntes, regréssi sunt in Jerúsalem, requiréntes eum. Et factum est, post tríduum invenérunt illum in templo sedéntem in médio doctórum, audiéntem illos et interrogántem eos. Stupébant autem omnes, qui eum audiébant, super prudéntia et respónsis ejus. Et vidéntes admiráti sunt. Et dixit Mater ejus ad illum: Fili, quid fecísti nobis sic? Ecce, pater tuus et ego doléntes quærebámus te. Et ait ad illos: Quid est, quod me quærebátis? Nesciebátis, quia in his, quæ Patris mei sunt, opórtet me esse? Et ipsi non intellexérunt verbum, quod locútus est ad eos. Et descéndit cum eis, et venit Názareth: et erat súbditus illis. Et Mater ejus conservábat ómnia verba hæc in corde suo. Et Jesus proficiébat sapiéntia et ætáte et grátia apud Deum et hómines."}],"Offertorium":[{"k":"ref","la":"Luc 2:22"},{"k":"text","la":"Tulérunt Jesum paréntes ejus in Jerúsalem, ut sísterent eum Dómino."}],"Secreta":[{"k":"text","la":"Placatiónis hóstiam offérimus tibi, Dómine, supplíciter deprecántes: ut, per intercessiónem Deíparae Vírginis cum beáto Ioseph, famílias nostras in pace et grátia tua fírmiter constítuas."},{"k":"macro","name":"Per eumdem"}],"Communio":[{"k":"ref","la":"Luc 2:51"},{"k":"text","la":"Descéndit Jesus cum eis, et venit Názareth, et erat súbditus illis."}],"Postcommunio":[{"k":"text","la":"Quos cœléstibus réficis sacraméntis, fac, Dómine Jesu, sanctæ Famíliæ tuæ exémpla júgiter imitári: ut in hora mortis nostræ, occurrénte gloriósa Vírgine Matre tua cum beáto Joseph; per te in ætérna tabernácula récipi mereámur:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Dominica infra Octavam Epiphaniæ"},{"k":"text","la":"Vota, quǽsumus, Dómine, supplicántis pópuli cœlésti pietáte proséquere: ut et, quæ agénda sunt, vídeant, et ad implénda, quæ víderint, convaléscant."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Dominica infra Octavam Epiphaniæ."},{"k":"text","la":"Oblátum tibi, Dómine, sacrifícium vivíficet nos semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Dominica infra Octavam Epiphaniæ."},{"k":"text","la":"Súpplices te rogámus, omnípotens Deus: ut, quos tuis réficis sacraméntis, tibi étiam plácitis móribus dignánter deservíre concédas."},{"k":"macro","name":"Per Dominum"}]},"hr":{"53bb512971f4fc0c":{"t":"Izr 23, 24-25, Ps 83, 2-3\n(Izr 23, 24-25) Radosno kliče otac pravednika. Neka se raduju tvoj otac i majka. Nek od veselja kliče ona koja te rodi. (Ps 83, 2-3) Kako su mili stanovi tvoji, Gospodine vojska! Duša mi gine od čežnje za dvorovima Gospodnjim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Izr 23, 24-25) Radosno kliče otac pravednika. Neka se raduju tvoj otac i majka. Nek od veselja kliče ona koja te rodi.","kn":"(Prov, 23; 24^ 25). Radosna kliče Otac Pravednika raduje se Otac Tvoj i majka Tvoja radosno kUce, koja Te rodila. (Ps. 83, 2, 3) Kako .su U sLe dup- “»d vojakama! Čezne o™ \". Slava","knRef":"Kniewald 1942, str. 72–73 (snimka 37) (OCR)"},"dd4557df560490f2":{"t":"<i>Pomolimo se</i>.\nGospodine Isuse Kriste, koji si podlažući se Mariji i Josipu posvetio obiteljski život neizrecivim krepostima, daj da nam njihovom pomoću bude na pouku primjer tvoje svete Obitelji, te da se s njom združimo u vječnosti:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3a77ec4b1e9c3b41":{"t":"Kol 3, 12-17\nČitanje Poslanice bl. Pavla apostola Kološanima. Braćo: kao Božji odabranici, sveti i ljubljeni, budite od srca milosrdni, blagi, ponizni, čedni, strpljivi. Podnosite jedan drugoga i opraštajte jedan drugome, ako se tko ima potužiti na drugoga. Kao što je Gospodin vama oprostio, tako i vi opraštajte. Nadasve imajte ljubav koja je veza savršenstva. I Kristov mir, na koji ste pozvani, neka u vašim srcima vlada kao u jednom tijelu. – Budite i zahvalni! Kristova riječ neka obilno stanuje u vama, u svakoj mudrosti. Poučavajte i potičite jedan drugoga psalmima, himnima, duhovnim pjesmama, na poticaj milosti pjevajte Bogu u svojim srcima. Sve što god govorite i činite neka bude u ime Gospodina Isusa Krista zahvaljujući Bogu Ocu po njemu.","kn":"Čitanje poslanice bi. Pavla apostola Kološanima (3, 12-17). Braćo! Kao Božji izabranici, sveti i ljubljeni, budite od srca milosrdni, blagi, ponizni, čedni, strpljivi. Podnosite jedan drugoga, i kao što je i Gospodin vama oprostio, tako i vi praštajte jedan drugomu, ako tko ima kakvu tužbu protiv drugOiga. Nada sve pak imajte ljubav, koja je veza savršenstva. I Kristov mir, na koji ste pozvani, neka zavlada u vašim srcima kao u jednom tijelu. Budite i zahvalni! Kristova riječ neka se u vama nastani obilno, u svakoj mudrosti, da se učite 1 opominjete jedan drugoga psalmima, himnima i duhovnim pjesmama zahvalno pjevajući Bogu u Evojim srcima, I sve štogod govorite ili činite, sve neka bude u ime Gospodina Isusa Krista zahvaljujući Bogu i Ocu po njemu.","knRef":"Kniewald 1942, str. 84–85 (snimka 43) (OCR)"},"8abd636595ecd51c":{"t":"Ps 26, 4, Ps 83, 5\nJedno samo molim od Gospodina, ovo tražim: da stanujem u domu Gospodnjem u sve dane svoga života. Blaženi koji stanuju u tvom domu, Gospodine. Oni će te slaviti u vijeke vjekova.\n\nIz 45, 15\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si doista sakriveni Kralj, Izraelov Bog, Spasitelj. <i>Aleluja</i>.","kn":"(Ps. 26, 4). Za jedno samo. molim, Gospodine i samo to tražim, da stanujem u domu Gospodnjemu u sve dane moga života. Da vidim Gospodine i da posjetim njegov hram. Aleluja, aleluja. (Ps. 83, 5). Blaženi, koji stanuju u domu Tvojemii. Gospodine, hvalit ću Te u vijeke vjekova. Aleluja.\n\nAleluja, aieluja^ (Iz. 45, 15): Doista, Ti si tajnoviti kralj, Ti si nas Bog Spasitelj, aleluja.","knRef":"Kniewald 1942, str. 774–775 (snimka 388) (OCR)"},"3f677878a41c5a6d":{"t":"Lk 2, 42-52\nSlijedi sveto Evanđelje po Luki. Kad je Isusu bilo dvanaest godina, njegovi roditelji pođu po blagdanskom običaju u Jeruzalem. Kad su prošli blagdani i oni se vraćali, dječak Isus ostade u Jeruzalemu, a da njegovi roditelji nisu znali. Misleći da je među suputnicima, išli su dan hoda, a onda ga stanu tražiti među rođacima i znancima. Ali, kako ga ne nađu, vrate se u Jeruzalem da ga traže. – Poslije tri dana nađu ga u hramu gdje sjedi među učiteljima, kako ih sluša i postavlja pitanja. Svi koji su ga slušali, divili su se njegovoj mudrosti i odgovorima. Kad ga opaze, vrlo se začude. A majka mu reče: »Sine, zašto si nam to učinio? Tvoj otac i ja žalosni smo te tražili.« On im odgovori: »Zašto ste me tražili? Zar niste znali da ja moram biti u onome što pripada mom Ocu?« A oni nisu shvatili njegovih riječi. – On tada pođe s njima i dođe u Nazaret i bio im je poslušan. Njegova je Majka sve ovo čuvala u svom srcu. A Isus je napredovao u mudrosti, dobi i milosti pred Bogom i ljudima.","kn":"t Slijedi sveto Evanđelje po Luki (2, 42-52). Kad je Isusu bilo dvanaest godina, njego.vi ''“''^\"telji po^ đoše po običaju blagdana u Jeruzalem. Kad su prošli, blagdani i oni se vraćali, dječak Isus ostade u Jeruzalemu, a da nijesu znali A jer su mislili, da je s društvom, posli su _dan . hoda i pitali za njega rođake .i ^ ® ne nađoše, vrate se u Jeruza.lem da ga Uaze. poslije tri dana nađu ga u hramu, gdje sjed-i medu uč teljima, kako. ih sluša i pita- I sv'i. koji su ga čuli, dlviU su se njegovoj, mudrosti i odgovorim^ I kad ga opaze, začude se, a, njegova mu maijka sLo, što Si nam tako učinio? Evo, ^ojmte i i, a tražili smo te žalosni! On odgovori. Zašto ste me tražili? Zar nijeste znali. da. jo treba da b«dem u kući svojega Oca? A oni .nijesu razumjeli sto m je kazao. I siđe ,s njima, i dođe a, Nazaret, i bm im ie pokoran. Njegova je majka sve ovo. cuv.^ svom srcu. a IS'US je napredovao, u mudrosti i dooi i milosti kod Boga i ljudi.","knRef":"Kniewald 1942, str. 72–73 (snimka 37) (OCR)"},"9d146a14b11d345d":{"t":"Lk 2, 22\nDoniješe Isusa njegovi roditelji u Jeruzalem da ga prikažu Gospodinu.","kn":"(Lk. 2, 22). Doniješe Isusa u. Jeruzalem,' da ga prikažu Gospodinu.","knRef":"Kniewald 1942, str. 72–73 (snimka 37) (OCR)"},"9f993b8334155c62":{"t":"Prikazujemo ti, Gospodine, žrtvu pomirnicu i ponizno te molimo, da po zagovoru Djevice Bogorodice i svetoga Josipa učvrstiš naše obitelji u miru i u svakoj milosti.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine, prikaizujemo Ti. žrtvu pomirniicu i ponizno Te molimo, da zagovorom djevičanske Bogorodi.ce i svetog Josipa utvrdiš naše obitelji u svojem miru i milosti, po listom G. n. I. K., Sinu ^omu, kO'ji s Tobom živi i kraljuje . . .","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"93e8203b4ea3a0a5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože: – jer kad se tvoj Jedinorođenac pojavio u našem smrtnom tijelu, on nas je novim svjetlom svoje besmrtnosti obnovio. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"bab0590616dfb9de":{"t":"Lk 2, 51\nIsus pođe s njima i dođe u Nazaret i bio im je poslušan.","kn":"(Lk. 2, 51). Siđe Isus s njima i dođe u Nazaret i bio im je pokoran.","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"5dc806c7316c28a8":{"t":"<i>Pomolimo se</i>.\nUčini, Gospodine Isuse, da mi koje krijepiš nebeskim otajstvima neprekidno nasljedujemo primjer tvoje svete Obitelji te zavrijedimo da nam u času smrti priteče u pomoć slavna Djevica, majka tvoja, sa svetim Josipom, a ti da nas primiš u vječne stanove.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine Isuse Kriste, koji nas oživljuješ nebeskim tajnama, da se uvijek ugledamo u primjer Tvoje svete Obitelji, te zavrijedlimo, da nam u smrtnom času dođe uBusret slavna Djevica Sa svetim Josipom, a Ti da nas primiš u vječni nebeski dom, koji živiš i kraljuješ u Bogom Ocem . . .","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"}}});
